<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pw,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['user_name']=$u['name'];go('/MediHome/account.php');}$err='Email or password is incorrect.';}$title='Login | MediHome';require 'includes/header.php';?><div class="formbox"><span class="eyebrow">Welcome back</span><h1>Log in</h1><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><form method="post"><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Password</label><input class="input" type="password" name="password" required></div><button class="btn">Log in</button></form><p>New here? <a href="/MediHome/register.php">Create an account</a></p></div><?php require 'includes/footer.php';?>